-- Oracle reference schema for the same disposable vertical-slice contract.
-- Run only against an isolated clone; this file is not a production migration.
create table slice_user (id number generated by default as identity primary key, username varchar2(255) unique not null, password_hash varchar2(128) not null, active number(1) not null);
create table slice_permission (id varchar2(64) primary key, parent_id varchar2(64) references slice_permission(id), name varchar2(255) not null);
create table slice_personnel (id number generated by default as identity primary key, name varchar2(255) not null, department varchar2(255) not null);
create table slice_equipment (id number generated by default as identity primary key, name varchar2(255) not null, status varchar2(32) not null);
create table slice_consumable (id number generated by default as identity primary key, code varchar2(64) unique not null, quantity number not null);
create table slice_report (department varchar2(255) primary key, record_count number not null);
